const fs = require('fs');
const input = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < input.length && input[pos] <= 32) pos++;
  let sign = 1;
  if (input[pos] === 45) {
    sign = -1;
    pos++;
  }
  let value = 0;
  while (pos < input.length && input[pos] > 32) {
    value = value * 10 + input[pos] - 48;
    pos++;
  }
  return value * sign;
}

const rows = nextInt();
const cols = nextInt();
const diffCols = cols - 1;
const heights = new Int32Array(diffCols);
const previous = new Int32Array(cols);
const current = new Int32Array(cols);
const stack = new Int32Array(diffCols);
let answer = 0;

for (let r = 0; r < rows; r++) {
  for (let c = 0; c < cols; c++) current[c] = nextInt();

  if (r > 0) {
    for (let c = 0; c < diffCols; c++) {
      const diff = previous[c] + current[c + 1] - previous[c + 1] - current[c];
      heights[c] = diff <= 0 ? heights[c] + 1 : 0;
    }

    let top = -1;
    for (let i = 0; i <= diffCols; i++) {
      const height = i === diffCols ? 0 : heights[i];

      while (top >= 0 && heights[stack[top]] > height) {
        const h = heights[stack[top--]];
        const left = top >= 0 ? stack[top] : -1;
        const width = i - left - 1;
        const area = (h + 1) * (width + 1);
        if (area > answer) answer = area;
      }

      if (i < diffCols) stack[++top] = i;
    }
  }

  for (let c = 0; c < cols; c++) previous[c] = current[c];
}

console.log(answer.toString());
